window.AUTH=window.AUTH||{};window.AUTH["16-9493"]={"d":"16-9493","id":"2017/16-9493","n":"Rosales-Mireles v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Rosales-Mireles, Florencio","date":"2017-11-29","url":"https://www.supremecourt.gov/DocketPDF/16/16-9493/22031/20171129175612614_16-9493ts.pdf","side":"pet","n":44},{"k":"respondent","label":"Brief of respondent United States","date":"2018-01-10","url":"https://www.supremecourt.gov/DocketPDF/16/16-9493/27456/20180110180947765_16-9493bsUnitedStates.pdf","side":"res","n":68},{"k":"reply","label":"Reply of petitioner Rosales-Mireles, Florencio","date":"2018-02-09","url":"https://www.supremecourt.gov/DocketPDF/16/16-9493/34984/20180209131848728_16-9493%20Reply%20Brief.pdf","side":"pet","n":17}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Argersinger v. Hamlin","cite":"407 U.S. 25","y":1972,"id":"1971/70-5015","sc":1,"by":{"0":"11","1":"28"},"q":[{"src":"brief","b":0,"text":"any deprivation of liberty is a serious matter,","cite":"407 U.S. 25, 41"},{"src":"brief","b":1,"text":"in determining how long a prison sentence will be.","cite":"407 U.S. 25, 41"}]},{"t":"case","label":"Baldwin v. New York","cite":"399 U.S. 66","y":1970,"id":"1969/188","sc":1,"by":{"0":"11"},"q":[{"src":"brief","b":0,"text":"[T]he prospect of imprisonment for however short a time will seldom be viewed … as a trivial or ‘petty’ matter and may well result in quite serious repercussions affecting [a defendant’s] career and his reputation.","cite":"399 U.S. 66, 73"}]},{"t":"case","label":"Barber v. Thomas","cite":"130 S. Ct. 2499","y":2010,"id":"2009/09-5201","sc":1,"by":{"0":"11"},"q":[{"src":"brief","b":0,"text":"time behind bars … some theoretical or mathematical concept. It is something real, even terrifying.","cite":"130 S. Ct. 2499, 2517"}]},{"t":"case","label":"Breithaupt v. Abram","cite":"352 U.S. 432","y":1957,"id":"1956/69","sc":1,"by":{"0":"20"},"q":[{"src":"brief","b":0,"text":"so ‘brutal’ and ‘offensive’ that it did not comport with traditional ideas of fair play and decency.","cite":"352 U.S. 432, 435"}]},{"t":"case","label":"Cty. of Sacramento v. Lewis","cite":"523 U.S. 833","y":1998,"id":"1997/96-1337","sc":1,"by":{"0":"7, 8, 19, 20","1":"34"},"q":[{"src":"brief","b":0,"text":"conduct intended to injure in some way unjustifiable by any government interest,","cite":"523 U.S. at 849"},{"src":"brief","b":0,"text":"may fairly be said to shock the contemporary conscience.","cite":"523 U.S. at 846"}]},{"t":"case","label":"Daniels v. Williams","cite":"474 U.S. 327","y":1986,"id":"1985/84-5872","sc":1,"by":{"0":"19, 20"},"q":[{"src":"brief","b":0,"text":"deliberate decisions of government officials to deprive a person of life, liberty, or property.","cite":"474 U.S. 327, 331"}]},{"t":"case","label":"Foucha v. Louisiana","cite":"504 U.S. 71","y":1992,"id":"1991/90-5844","sc":1,"by":{"0":"11"},"q":[{"src":"brief","b":0,"text":"clear that commitment for any purpose constitutes a significant deprivation of liberty.","cite":"504 U.S. 71, 80"}]},{"t":"case","label":"Gall v. United States","cite":"552 U.S. 38","y":2007,"id":"2007/06-7949","sc":1,"by":{"0":"6, 12","1":"2, 20","2":"7, 13"},"q":[{"src":"brief","b":0,"text":"the starting point and the initial benchmark","cite":"552 U.S. at 49"}]},{"t":"case","label":"Glover v. United States","cite":"531 U.S. 198","y":2001,"id":"2000/99-8576","sc":1,"by":{"0":"11, 22","2":"13"},"q":[{"src":"brief","b":0,"text":"any amount of actual jail time has Sixth Amendment significance.","cite":"531 U.S. 198, 203"}]},{"t":"case","label":"Henderson v. United States","cite":"568 U.S. 266","y":2013,"id":"2012/11-9307","sc":1,"by":{"0":"21","1":"19, 26","2":"10"},"q":[{"src":"brief","b":0,"text":"plain error review is not a grading system for trial judges[,]","cite":"568 U.S. 266, 278"},{"src":"brief","b":2,"text":"[i]f there is a lawyer who would deliberately forgo objection now because he perceives some slightly expanded chance to argue for ‘plain error’ later, we suspect that, like the unicorn, he finds his home in the imagination, not the courtroom.","cite":"568 U.S. 266, 276"}]},{"t":"case","label":"Hicks v. United States","cite":"137 S. Ct. 2000","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./137/2000/","sc":1,"by":{"0":"1, 2, 3, 10, 11","2":"7"},"q":[{"src":"brief","b":0,"text":"allow[ ] individuals to linger longer in prison than the law requires[.]","cite":"137 S. Ct. 2000, 2000–01"},{"src":"brief","b":0,"text":"the possibility that [courts] might permit the government to deny someone his liberty longer than the law permits only because [they] refuse to correct an obvious judicial error.","cite":"137 S. Ct. at 2001"},{"src":"brief","b":2,"text":"allow[ing] individuals to linger longer in prison than the law requires,","cite":"137 S. Ct. 2000, 2000–01"}]},{"t":"case","label":"Johnson v. United States","cite":"520 U.S. 461","y":1997,"id":"1996/96-203","sc":1,"by":{"0":"9, 10","1":"16, 17, 29"}},{"t":"case","label":"Molina-Martinez v. United States","cite":"136 S. Ct. 1338","y":2016,"id":"2015/14-8913","sc":1,"by":{"0":"passim","1":"3, 19, 21, 23, 25, 26","2":"passim"},"q":[{"src":"brief","b":0,"text":"the Fifth Circuit stands generally apart from other Courts of Appeals with respect to its consideration of unpreserved Guidelines errors.","cite":"136 S. Ct. at 1345"},{"src":"brief","b":0,"text":"are complex, and so there will be instances when a district court’s sentencing of a defendant within the framework of an incorrect Guidelines range goes unnoticed.","cite":"136 S. Ct. at 1342"},{"src":"brief","b":1,"text":"fail[s] to object to the miscalculation [of the Guidelines range], appellate review of the error is governed by Federal Rule of Criminal Procedure 52(b).","cite":"136 S. Ct. 1338, 1343"},{"src":"brief","b":1,"text":"‘[i]n most cases,’ * * * a showing that the district court ‘mistakenly deemed applicable an incorrect, higher Guidelines range’ should ‘suffice for relief.’","cite":"136 S. Ct. at 1346"},{"src":"argument","who":"Ms. Davidson","text":"As the Court has recognized in Peugh and Molina-Martinez, the sentencing guidelines provide the essential framework for federal sentencing, and there is a well-documented anchoring effect so that when there is an erroneously high guidelines range, there's a significant risk that the defendant was sentenced to a longer prison time than he otherwise would have had the district court not been influenced by the error itself."},{"src":"argument","who":"Ms. Davidson","text":"And while it is true that Molina-Martinez looks at the anchoring effect of the guideline to show that the guideline error itself can be evidence of an effect on substantial rights, the resulting harm of that is a longer prison sentence."},{"src":"argument","who":"Ms. Davidson","text":"As to relative cost, certainly, there's always some cost involved to resentencing, but the fact is it is a lower cost than having a new trial, for example. The Court recognized that resentencing doesn't present the same amount of costs in Molina-Martinez. And -"}]},{"t":"case","label":"Peugh v. United States","cite":"133 S. Ct. 2072","y":2013,"id":"2012/12-62","sc":1,"by":{"0":"12"},"q":[{"src":"brief","b":0,"text":"in a real sense the basis for the sentence","cite":"133 S. Ct. 2072, 2083"},{"src":"brief","b":0,"text":"when a Guidelines range moves up or down, offenders’ sentences move with it.","cite":"133 S. Ct. at 2084"},{"src":"argument","who":"Ms. Davidson","text":"As the Court has recognized in Peugh and Molina-Martinez, the sentencing guidelines provide the essential framework for federal sentencing, and there is a well-documented anchoring effect so that when there is an erroneously high guidelines range, there's a significant risk that the defendant was sentenced to a longer prison time than he otherwise would have had the district court not been influenced by the error itself."}]},{"t":"case","label":"Puckett v. United States","cite":"556 U.S. 129","y":2009,"id":"2008/07-9712","sc":1,"by":{"0":"7, 10, 17","1":"passim","2":"7"},"q":[{"src":"brief","b":0,"text":"on a case-specific and fact-intensive basis.","cite":"556 U.S. 129, 142–43"},{"src":"brief","b":1,"text":"Failure to abide by this contemporaneous-objection rule ordinarily precludes the raising on appeal of the unpreserved claim of trial error.","cite":"556 U.S. 129, 135"},{"src":"brief","b":1,"text":"authority to remedy [a forfeited] error.","cite":"556 U.S. at 134"}]},{"t":"case","label":"Rita v. United States","cite":"551 U.S. 338","y":2007,"id":"2006/06-5754","sc":1,"by":{"0":"14, 15, 22","1":"2, 21, 30, 31"},"q":[{"src":"brief","b":0,"text":"uniformity in sentencing … imposed by different federal courts for similar criminal conduct, as well as proportionality in sentencing through a system that imposes appropriately different sentences for criminal conduct of different severity.","cite":"551 U.S. 338, 349"},{"src":"brief","b":1,"text":"The sentencing judge, as a matter of process, will normally begin by considering the presentence report and its interpretation of the Guidelines.","cite":"551 U.S. 338, 351"},{"src":"brief","b":1,"text":"‘through a system that imposes appropriately different sentences for criminal conduct of different severity.’","cite":"551 U.S. at 349"},{"src":"argument","who":"Mr. Ellis","text":"It was subsequently - Justice Scalia subsequently wrote about it in a concurrence in Rita, and then the Court wrote about it in Footnote 7 of the majority opinion in Greenlaw."}]},{"t":"case","label":"Rochin v. California","cite":"342 U.S. 165","y":1952,"id":"1940-1955/342us165","sc":1,"by":{"0":"19, 20","1":"34"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"by":{"0":"12","1":"31"},"q":[{"src":"argument","who":"Justice Alito","text":"Well, that \"shall\" is part of the mandatory regime. I thought that was declared unconstitutional in Booker."},{"src":"argument","who":"Mr. Ellis","text":"And you get it by saying that -- by recognizing that that provision was enacted as part of the mandatory guideline system, that what it was doing was implementing 3742(e), which this Court said was unconstitutional in Booker and therefore struck it."},{"src":"argument","who":"Justice Breyer","text":"Did we declare this -- this section unconstitutional in Booker? I mean, we tried to save as much as we could, and I don't know why we wouldn't have saved this one."}]},{"t":"case","label":"United States v. Castillo-Casiano","cite":"198 F.3d 787","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/198/787/","by":{"0":"13, 15"},"q":[{"src":"brief","b":0,"text":"easy to see why prejudicial sentencing errors undermine the fairness, integrity, and public reputation of [those] proceedings","cite":"198 F.3d 787, 792"},{"src":"brief","b":0,"text":"a longer sentence than might have been imposed had the court not plainly erred","cite":"198 F.3d at 792"}]},{"t":"case","label":"United States v. Corso","cite":"549 F.3d 921","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/549/921/","by":{"0":"17","1":"24"},"q":[{"src":"brief","b":0,"text":"unreasonably exceed[ ] the Guidelines range determined by the Court.","cite":"549 F.3d 921, 924"}]},{"t":"case","label":"United States v. Dahl","cite":"833 F.3d 345","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/833/345/","by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"exercise [its] discretion to recognize [the] plain error,","cite":"833 F.3d 345, 359"}]},{"t":"case","label":"United States v. Escalante-Reyes","cite":"689 F.3d 415","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/689/415/","by":{"0":"20","1":"9, 33"},"q":[{"src":"brief","b":0,"text":"impugn[ed] the integrity of our judicial system with incompetent or malicious decisions.","cite":"689 F.3d 415, 436"},{"src":"brief","b":1,"text":"seriously affect[ed] the fairness, integrity or public reputation of judicial proceedings.","cite":"689 F.3d 415, 419"}]},{"t":"case","label":"United States v. Figueroa-Ocasio","cite":"805 F.3d 360","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/805/360/","by":{"0":"16"}},{"t":"case","label":"United States v. Frady","cite":"456 U.S. 152","y":1982,"id":"1981/80-1595","sc":1,"by":{"0":"19","1":"11, 14, 17, 25"},"q":[{"src":"brief","b":0,"text":"that obvious injustice be promptly redressed.","cite":"456 U.S. 152, 163"},{"src":"brief","b":1,"text":"our insistence that obvious injustice be promptly redressed.","cite":"456 U.S. 152, 163"},{"src":"brief","b":1,"text":"The plain error rule is not a run-of-the-mill remedy.","cite":"456 U.S. at 163 n.14"}]},{"t":"case","label":"United States v. Jaimes-Jaimes","cite":"406 F.3d 845","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/406/845/","by":{"0":"21"}},{"t":"case","label":"United States v. Langford","cite":"516 F.3d 205","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/516/205/","by":{"0":"14"},"q":[{"src":"brief","b":0,"text":"actually affords deference and respect for the District Court judge.","cite":"516 F.3d 205, 220"}]},{"t":"case","label":"United States v. Martinez-Rios","cite":"143 F.3d 662","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/143/662/","by":{"0":"11"}},{"t":"case","label":"United States v. Olano","cite":"507 U.S. 725","y":1993,"id":"1992/91-1306","sc":1,"by":{"0":"passim","1":"passim","2":"2, 9"},"q":[{"src":"brief","b":0,"text":"should correct a plain forfeited error affecting substantial rights if the error seriously affects the fairness, integrity, or public reputation of judicial proceedings.","cite":"507 U.S. 725, 736"},{"src":"brief","b":0,"text":"the error seriously affect[s] the fairness, integrity, or public reputation of judicial proceedings.","cite":"507 U.S. at 736"},{"src":"brief","b":1,"text":"the discretion afforded by Rule 52(b) * * * illusory.","cite":"507 U.S. at 737"},{"src":"brief","b":1,"text":"seriously affect[s] the fairness, integrity or public reputation of judicial proceedings.","cite":"507 U.S. 725, 736"},{"src":"argument","who":"Ms. Davidson","text":"I think the approach that's applied by the majority of circuits actually gives vitality to the plain error standard, as the Court expressed it in Olano."},{"src":"argument","who":"Justice Gorsuch","text":"Davidson, I was wondering about our -- our standard in Olano and the fourth prong, talking about fairness, reputation, integrity of judicial proceedings, and where it came from."},{"src":"argument","who":"Ms. Davidson","text":"Well, I'm aware of that history, but I also can't ignore how often cited the Court has restated Olano's formulation, so I don't have a position in - in going back to a pure disjunctive, but I would like to point out that in articulating that -- what became the fourth-prong standard in Atkinson, Atkinson cites Brasfield, and in Brasfield, it's an example where the Court recognized a type of error that, by virtue of inquiring into the numerical division among the jurors, that inquiry itself impugned the system."}]},{"t":"case","label":"United States v. Pennington","cite":"667 F.3d 953","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/667/953/","by":{"0":"11"},"q":[{"src":"brief","b":0,"text":"impose a sentence sufficient, but no greater than necessary.","cite":"667 F.3d 953, 957"}]},{"t":"case","label":"United States v. Rushton","cite":"738 F.3d 854","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/738/854/","by":{"0":"22"}},{"t":"case","label":"United States v. Sabillon-Umana","cite":"772 F.3d 1328","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/1328/","by":{"0":"15, 16"},"q":[{"src":"argument","who":"Justice Ginsburg","text":"Did the Tenth Circuit in, what is it, Sabillon-Umana overstate it when the Tenth Circuit said that the third and fourth prongs of the plain error test align in these guidelines miscalculations?"}]},{"t":"case","label":"United States v. Syme","cite":"276 F.3d 131","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/276/131/","by":{"0":"16"}},{"t":"case","label":"United States v. Wernick","cite":"691 F.3d 108","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/691/108/","by":{"0":"16, 17"},"q":[{"src":"brief","b":0,"text":"adversely affect the public perception of the fairness of judicial pro- ceedings.","cite":"691 F.3d 108, 118"}]},{"t":"case","label":"United States v. Westover","cite":"435 F.3d 1273","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/435/1273/","by":{"0":"18","1":"24, 25"},"q":[{"src":"brief","b":1,"text":"prevent th[e] appeal from being moot.","cite":"435 F.3d at 1277"}]},{"t":"case","label":"Wall v. Kholi","cite":"562 U.S. 545","y":2011,"id":"2010/09-868","sc":1,"by":{"0":"9"},"q":[{"src":"brief","b":0,"text":"judgment[,] to be guided by sound legal principles.","cite":"562 U.S. 545, 559"}]},{"t":"case","label":"Williams v. Pennsylvania","cite":"136 S. Ct. 1899","y":2016,"id":"2015/15-5040","sc":1,"by":{"0":"21"}},{"t":"case","label":"Williams v. United States","cite":"503 U.S. 193","y":1992,"id":"1991/90-6297","sc":1,"by":{"0":"22","2":"13"},"q":[{"src":"brief","b":0,"text":"substitute [their] judgment for that of the sentencing court as to the appropriateness of a particular sentence.","cite":"503 U.S. 193, 205"}]},{"t":"usc","label":"18 U.S.C. § 3552","url":"https://www.law.cornell.edu/uscode/text/18/3552","subs":["(a)"],"stext":{"head":"§3552. Presentence reports","paras":[[0,"(a) Presentence Investigation and Report by Probation Officer.—A United States probation officer shall make a presentence investigation of a defendant that is required pursuant to the provisions of Rule 32(c) of the Federal Rules of Criminal Procedure, and shall, before the imposition of sentence, report the results of the investigation to the court."],[0,"(b) Presentence Study and Report by Bureau of Prisons.—If the court, before or after its receipt of a report specified in subsection (a) or (c), desires more information than is otherwise available to it as a basis for determining the sentence to be imposed on a defendant found guilty of a misdemeanor or felony, it may order a study of the defendant. The study shall be conducted in the local community by qualified consultants unless the sentencing judge finds that there is a compelling reason for the study to be done by the Bureau of Prisons or there are no adequate professional resources available in the local community to perform the study. The period of the study shall be no more than sixty days. The order shall specify the additional information that the court needs before determining the sentence to be imposed. Such an order shall be treated for administrative purposes as a provisional sentence of imprisonment for the maximum term authorized by section 3581(b) for the offense committed. The study shall inquire into such matters as are specified by the court and any other matters that the Bureau of Prisons or the professional consultants believe are pertinent to the factors set forth in section 3553(a). The period of the study may, in the discretion of the court, be extended for an additional period of not more than sixty days. By the expiration of the period of the study, or by the expiration of any extension granted by the court, the United States marshal shall, if the defendant is in custody, return the defendant to the court for final sentencing. The Bureau of Prisons or the professional consultants shall provide the court with a written report of the pertinent results of the study and make to the court whatever recommendations the Bureau or the consultants believe will be helpful to a proper resolution of the case. The report shall include recommendations of the Bureau or the consultants concerning the guidelines and policy statements, promulgated by the Sentencing Commission pursuant to 28 U.S.C. 994(a), that they believe are applicable to the defendant's case. After receiving the report and the recommendations, the court shall proceed finally to sentence the defendant in accordance with the sentencing alternatives and procedures available under this chapter."],[0,"(c) Presentence Examination and Report by Psychiatric or Psychological Examiners.—If the court, before or after its receipt of a report specified in subsection (a) or (b) desires more information than is otherwise available to it as a basis for determining the mental condition of the defendant, the court may order the same psychiatric or psychological examination and report thereon as may be ordered under section 4244(b) of this title."],[0,"(d) Disclosure of Presentence Reports.—The court shall assure that a report filed pursuant to this section is disclosed to the defendant, the counsel for the defendant, and the attorney for the Government at least ten days prior to the date set for sentencing, unless this minimum period is waived by the defendant. The court shall provide a copy of the presentence report to the attorney for the Government to use in collecting an assessment, criminal fine, forfeiture or restitution imposed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3552?type=usc&year=mostrecent&link-type=html"},"by":{"0":"12","1":"2, 2"},"q":[{"src":"brief","b":1,"text":"before the imposition of sentence, report the results of the investigation to the court.","cite":"18 U.S.C. 3552(a)"}]},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(1)","(a)(5)","(c)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"by":{"0":"11, 12, 14","1":"22, 22, 22, 22"}},{"t":"usc","label":"18 U.S.C. § 3742","url":"https://www.law.cornell.edu/uscode/text/18/3742","subs":["(f)(1)","(g)"],"stext":{"head":"§3742. Review of a sentence","paras":[[0,"(a) Appeal by a Defendant.—A defendant may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines; or"],[1,"(3) is greater than the sentence specified in the applicable guideline range to the extent that the sentence includes a greater fine or term of imprisonment, probation, or supervised release than the maximum established in the guideline range, or includes a more limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the maximum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"(b) Appeal by the Government.—The Government may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is less than the sentence specified in the applicable guideline range to the extent that the sentence includes a lesser fine or term of imprisonment, probation, or supervised release than the minimum established in the guideline range, or includes a less limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the minimum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"The Government may not further prosecute such appeal without the personal approval of the Attorney General, the Solicitor General, or a deputy solicitor general designated by the Solicitor General."],[0,"(c) Plea Agreements.—In the case of a plea agreement that includes a specific sentence under rule 11(e)(1)(C) of the Federal Rules of Criminal Procedure—"],[1,"(1) a defendant may not file a notice of appeal under paragraph (3) or (4) of subsection (a) unless the sentence imposed is greater than the sentence set forth in such agreement; and"],[1,"(2) the Government may not file a notice of appeal under paragraph (3) or (4) of subsection (b) unless the sentence imposed is less than the sentence set forth in such agreement."],[0,"(d) Record on Review.—If a notice of appeal is filed in the district court pursuant to subsection (a) or (b), the clerk shall certify to the court of appeals—"],[1,"(1) that portion of the record in the case that is designated as pertinent by either of the parties;"],[1,"(2) the presentence report; and"],[1,"(3) the information submitted during the sentencing proceeding."],[0,"(e) Consideration.—Upon review of the record, the court of appeals shall determine whether the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is outside the applicable guideline range, and"],[2,"(A) the district court failed to provide the written statement of reasons required by section 3553(c);"],[2,"(B) the sentence departs from the applicable guideline range based on a factor that—"],[3,"(i) does not advance the objectives set forth in section 3553(a)(2); or"],[3,"(ii) is not authorized under section 3553(b); or"],[3,"(iii) is not justified by the facts of the case; or"],[2,"(C) the sentence departs to an unreasonable degree from the applicable guidelines range, having regard for the factors to be considered in imposing a sentence, as set forth in section 3553(a) of this title and the reasons for the imposition of the particular sentence, as stated by the district court pursuant to the provisions of section 3553(c); or"],[1,"(4) was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable."],[0,"The court of appeals shall give due regard to the opportunity of the district court to judge the credibility of the witnesses, and shall accept the findings of fact of the district court unless they are clearly erroneous and, except with respect to determinations under subsection (3)(A) or (3)(B), shall give due deference to the district court's application of the guidelines to the facts. With respect to determinations under subsection (3)(A) or (3)(B), the court of appeals shall review de novo the district court's application of the guidelines to the facts."],[0,"(f) Decision and Disposition.—If the court of appeals determines that—"],[1,"(1) the sentence was imposed in violation of law or imposed as a result of an incorrect application of the sentencing guidelines, the court shall remand the case for further sentencing proceedings with such instructions as the court considers appropriate;"],[1,"(2) the sentence is outside the applicable guideline range and the district court failed to provide the required statement of reasons in the order of judgment and commitment, or the departure is based on an impermissible factor, or is to an unreasonable degree, or the sentence was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable, it shall state specific reasons for its conclusions and—"],[2,"(A) if it determines that the sentence is too high and the appeal has been filed under subsection (a), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[2,"(B) if it determines that the sentence is too low and the appeal has been filed under subsection (b), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[1,"(3) the sentence is not described in paragraph (1) or (2), it shall affirm the sentence."],[0,"(g) Sentencing Upon Remand.—A district court to which a case is remanded pursuant to subsection (f)(1) or (f)(2) shall resentence a defendant in accordance with section 3553 and with such instructions as may have been given by the court of appeals, except that—"],[1,"(1) In determining the range referred to in subsection 3553(a)(4), the court shall apply the guidelines issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, and that were in effect on the date of the previous sentencing of the defendant prior to the appeal, together with any amendments thereto by any act of Congress that was in effect on such date; and"],[1,"(2) The court shall not impose a sentence outside the applicable guidelines range except upon a ground that—"],[2,"(A) was specifically and affirmatively included in the written statement of reasons required by section 3553(c) in connection with the previous sentencing of the defendant prior to the appeal; and"],[2,"(B) was held by the court of appeals, in remanding the case, to be a permissible ground of departure."],[0,"(h) Application to a Sentence by a Magistrate Judge.—An appeal of an otherwise final sentence imposed by a United States magistrate judge may be taken to a judge of the district court, and this section shall apply (except for the requirement of approval by the Attorney General or the Solicitor General in the case of a Government appeal) as though the appeal were to a court of appeals from a sentence imposed by a district court."],[0,"(i) Guideline Not Expressed as a Range.—For the purpose of this section, the term \"guideline range\" includes a guideline range having the same upper and lower limits."],[0,"(j) Definitions.—For purposes of this section—"],[1,"(1) a factor is a \"permissible\" ground of departure if it—"],[2,"(A) advances the objectives set forth in section 3553(a)(2); and"],[2,"(B) is authorized under section 3553(b); and"],[2,"(C) is justified by the facts of the case; and"],[1,"(2) a factor is an \"impermissible\" ground of departure if it is not a permissible factor within the meaning of subsection (j)(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3742?type=usc&year=mostrecent&link-type=html"},"by":{"0":"16","1":"31, 31, 32"},"q":[{"src":"brief","b":0,"text":"imposed as a result of an incorrect application of the sentencing guidelines, the court shall remand the case for further sentencing proceedings.","cite":"18 U.S.C. § 3742(f)(1)"}]},{"t":"usc","label":"28 U.S.C. § 991","url":"https://www.law.cornell.edu/uscode/text/28/991","subs":["(b)"],"by":{"0":"14"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","stext":{"head":"§994. Duties of the Commission","paras":[[0,"(a) The Commission, by affirmative vote of at least four members of the Commission, and pursuant to its rules and regulations and consistent with all pertinent provisions of any Federal statute shall promulgate and distribute to all courts of the United States and to the United States Probation System—"],[1,"(1) guidelines, as described in this section, for use of a sentencing court in determining the sentence to be imposed in a criminal case, including—"],[2,"(A) a determination whether to impose a sentence to probation, a fine, or a term of imprisonment;"],[2,"(B) a determination as to the appropriate amount of a fine or the appropriate length of a term of probation or a term of imprisonment;"],[2,"(C) a determination whether a sentence to a term of imprisonment should include a requirement that the defendant be placed on a term of supervised release after imprisonment, and, if so, the appropriate length of such a term;"],[2,"(D) a determination whether multiple sentences to terms of imprisonment should be ordered to run concurrently or consecutively; and"],[2,"(E) a determination under paragraphs (6) and (11) 1 of section 3563(b) of title 18;"],[1,"(2) general policy statements regarding application of the guidelines or any other aspect of sentencing or sentence implementation that in the view of the Commission would further the purposes set forth in section 3553(a)(2) of title 18, United States Code, including the appropriate use of—"],[2,"(A) the sanctions set forth in sections 3554, 3555, and 3556 of title 18;"],[2,"(B) the conditions of probation and supervised release set forth in sections 3563(b) and 3583(d) of title 18;"],[2,"(C) the sentence modification provisions set forth in sections 3563(c), 3564, 3573, and 3582(c) of title 18;"],[2,"(D) the fine imposition provisions set forth in section 3572 of title 18;"],[2,"(E) the authority granted under rule 11(e)(2) of the Federal Rules of Criminal Procedure to accept or reject a plea agreement entered into pursuant to rule 11(e)(1); and"],[2,"(F) the temporary release provisions set forth in section 3622 of title 18, and the prerelease custody provisions set forth in section 3624(c) of title 18; and"],[1,"(3) guidelines or general policy statements regarding the appropriate use of the provisions for revocation of probation set forth in section 3565 of title 18, and the provisions for modification of the term or conditions of supervised release and revocation of supervised release set forth in section 3583(e) of title 18."],[0,"(b)(1) The Commission, in the guidelines promulgated pursuant to subsection (a)(1), shall, for each category of offense involving each category of defendant, establish a sentencing range that is consistent with all pertinent provisions of title 18, United States Code."],[0,"(2) If a sentence specified by the guidelines includes a term of imprisonment, the maximum of the range established for such a term shall not exceed the minimum of that range by more than the greater of 25 percent or 6 months, except that, if the minimum term of the range is 30 years or more, the maximum may be life imprisonment."],[0,"(c) The Commission, in establishing categories of offenses for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) the grade of the offense;"],[1,"(2) the circumstances under which the offense was committed which mitigate or aggravate the seriousness of the offense;"],[1,"(3) the nature and degree of the harm caused by the offense, including whether it involved property, irreplaceable property, a person, a number of persons, or a breach of public trust;"],[1,"(4) the community view of the gravity of the offense;"],[1,"(5) the public concern generated by the offense;"],[1,"(6) the deterrent effect a particular sentence may have on the commission of the offense by others; and"],[1,"(7) the current incidence of the offense in the community and in the Nation as a whole."],[0,"(d) The Commission in establishing categories of defendants for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, with respect to a defendant, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) age;"],[1,"(2) education;"],[1,"(3) vocational skills;"],[1,"(4) mental and emotional condition to the extent that such condition mitigates the defendant's culpability or to the extent that such condition is otherwise plainly relevant;"],[1,"(5) physical condition, including drug dependence;"],[1,"(6) previous employment record;"],[1,"(7) family ties and responsibilities;"],[1,"(8) community ties;"],[1,"(9) role in the offense;"],[1,"(10) criminal history; and"],[1,"(11) degree of dependence upon criminal activity for a livelihood."],[0,"The Commission shall assure that the guidelines and policy statements are entirely neutral as to the race, sex, national origin, creed, and socioeconomic status of offenders."],[0,"(e) The Commission shall assure that the guidelines and policy statements, in recommending a term of imprisonment or length of a term of imprisonment, reflect the general inappropriateness of considering the education, vocational skills, employment record, family ties and responsibilities, and community ties of the defendant."],[0,"(f) The Commission, in promulgating guidelines pursuant to subsection (a)(1), shall promote the purposes set forth in section 991(b)(1), with particular attention to the requirements of subsection 991(b)(1)(B) for providing certainty and fairness in sentencing and reducing unwarranted sentence disparities."],[0,"(g) The Commission, in promulgating guidelines pursuant to subsection (a)(1) to meet the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code, shall take into account the nature and capacity of the penal, correctional, and other facilities and services available, and shall make recommendations concerning any change or expansion in the nature or capacity of such facilities and services that might become necessary as a result of the guidelines promulgated pursuant to the provisions of this chapter. The sentencing guidelines prescribed under this chapter shall be formulated to minimize the likelihood that the Federal prison population will exceed the capacity of the Federal prisons, as determined by the Commission."],[0,"(h) The Commission shall assure that the guidelines specify a sentence to a term of imprisonment at or near the maximum term authorized for categories of defendants in which the defendant is eighteen years old or older and—"],[1,"(1) has been convicted of a felony that is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46; and"],[1,"(2) has previously been convicted of two or more prior felonies, each of which is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46."],[0,"(i) The Commission shall assure that the guidelines specify a sentence to a substantial term of imprisonment for categories of defendants in which the defendant—"],[1,"(1) has a history of two or more prior Federal, State, or local felony convictions for offenses committed on different occasions;"],[1,"(2) committed the offense as part of a pattern of criminal conduct from which the defendant derived a substantial portion of the defendant's income;"],[1,"(3) committed the offense in furtherance of a conspiracy with three or more persons engaging in a pattern of racketeering activity in which the defendant participated in a managerial or supervisory capacity;"],[1,"(4) committed a crime of violence that constitutes a felony while on release pending trial, sentence, or appeal from a Federal, State, or local felony for which he was ultimately convicted; or"],[1,"(5) committed a felony that is set forth in section 401 or 1010 of the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 841 and 960), and that involved trafficking in a substantial quantity of a controlled substance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/994?type=usc&year=mostrecent&link-type=html"},"by":{"0":"14, 15"},"q":[{"src":"brief","b":0,"text":"providing certainty and fairness in sentencing and reducing unwarranted sentence disparities.","cite":"28 U.S.C. § 994(f)"}]},{"t":"rule","label":"Fed. R. Crim. P. 32","url":"https://www.law.cornell.edu/rules/frcrmp/rule_32","subs":["(c)"],"by":{"0":"12"}},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(b)"],"by":{"0":"1, 6"}},{"t":"case","label":"Beckles v. United States","cite":"137 S. Ct. 886","y":2017,"id":"2016/15-8544","sc":1,"by":{"1":"2, 20"}},{"t":"case","label":"Black v. Cutter Labs.","cite":"351 U.S. 292","y":1956,"id":"1955/92","sc":1,"by":{"1":"11, 36"},"q":[{"src":"brief","b":1,"text":"reviews judgments, not statements in opinions,","cite":"351 U.S. 292, 297"}]},{"t":"case","label":"Brasfield v. United States","cite":"272 U.S. 448","y":1926,"id":"scdb/1926-005","sc":1,"by":{"1":"19","2":"6"},"q":[{"src":"brief","b":1,"text":"essential to the fair and impartial conduct","cite":"272 U.S. 448, 450"},{"src":"brief","b":2,"text":"bring[ ] to bear in some degree, serious, although not measurable, an improper influence upon the [sentencing court].","cite":"272 U.S. 448, 450"},{"src":"argument","who":"Ms. Davidson","text":"Well, I'm aware of that history, but I also can't ignore how often cited the Court has restated Olano's formulation, so I don't have a position in - in going back to a pure disjunctive, but I would like to point out that in articulating that -- what became the fourth-prong standard in Atkinson, Atkinson cites Brasfield, and in Brasfield, it's an example where the Court recognized a type of error that, by virtue of inquiring into the numerical division among the jurors, that inquiry itself impugned the system."}]},{"t":"case","label":"Burns v. United States","cite":"501 U.S. 129","y":1991,"id":"1990/89-7260","sc":1,"by":{"1":"2"}},{"t":"case","label":"Greenlaw v. United States","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"a solidly grounded rule of appellate practice.","cite":"554 U.S. 237, 250"},{"src":"argument","who":"Mr. Ellis","text":"In -- in Footnote 7 of Greenlaw, this Court specifically flagged that the discussion there is not meant to settle the question as to whether 3742(f)(1) -"},{"src":"argument","who":"Mr. Ellis","text":"It was subsequently - Justice Scalia subsequently wrote about it in a concurrence in Rita, and then the Court wrote about it in Footnote 7 of the majority opinion in Greenlaw."}]},{"t":"case","label":"Jones v. United States","cite":"527 U.S. 373","y":1999,"id":"1998/97-9361","sc":1,"by":{"1":"15, 17, 23"},"q":[{"src":"brief","b":1,"text":"appellate court should exercise its discretion to correct plain error only if it ‘seriously affect[s] the fairness, integrity, or public reputation of judicial proceedings.’","cite":"527 U.S. 373, 389"}]},{"t":"case","label":"Padilla v. Kentucky","cite":"559 U.S. 356","y":2010,"id":"2009/08-651","sc":1,"by":{"1":"31"}},{"t":"case","label":"Peguero v. United States","cite":"526 U.S. 23","y":1999,"id":"1998/97-9217","sc":1,"by":{"1":"14"},"q":[{"src":"brief","b":1,"text":"as binding as any statute duly enacted by Congress,","cite":"526 U.S. 23, 29"}]},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"by":{"1":"27, 30, 32, 33"},"q":[{"src":"brief","b":1,"text":"appl[y] both at a defendant’s initial sentencing and at any subsequent resentencing after a sentence has been set aside on appeal.","cite":"562 U.S. at 490"},{"src":"argument","who":"Mr. Ellis","text":"Number 1, in Pepper, this Court recognized that the sort of disparity that Congress is -- was worried about in the guidelines context is not the sort of disparity that's caused by the ordinary rules of appellate procedure."}]},{"t":"case","label":"Sibron v. New York","cite":"392 U.S. 40","y":1968,"id":"1967/63","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"reverberate beyond the length of imprison- ment.","cite":"392 U.S. 40, 55"}]},{"t":"case","label":"United States v. Alegria-Alvarez","cite":"471 Fed. Appx. 271","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./471/271/","by":{"1":"35"}},{"t":"case","label":"United States v. Andino-Ortega","cite":"608 F.3d 305","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/608/305/","by":{"1":"35"}},{"t":"case","label":"United States v. Atkinson","cite":"297 U.S. 157","y":1936,"id":"scdb/1935-082","sc":1,"by":{"1":"3, 11, 12, 16, 23"},"q":[{"src":"brief","b":1,"text":"seriously affect[s] the fairness, integrity or public reputation of judicial proceedings.","cite":"297 U.S. 157, 160"},{"src":"argument","who":"Justice Gorsuch","text":"And I traced it back to Atkinson, a 1936 opinion. I know you've cited that. And I wanted your thoughts about that, because in Atkinson, it said district courts should be guided by the following test in when to exercise their discretion to correct a plain error and suggested that they should correct a plain error whenever it's obvious or when it affects the fairness, integrity, or public reputation of judicial proceedings."},{"src":"argument","who":"Ms. Davidson","text":"Well, I'm aware of that history, but I also can't ignore how often cited the Court has restated Olano's formulation, so I don't have a position in - in going back to a pure disjunctive, but I would like to point out that in articulating that -- what became the fourth-prong standard in Atkinson, Atkinson cites Brasfield, and in Brasfield, it's an example where the Court recognized a type of error that, by virtue of inquiring into the numerical division among the jurors, that inquiry itself impugned the system."}]},{"t":"case","label":"United States v. Barbosa","cite":"698 Fed. Appx. 206","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./698/206/","by":{"1":"35"}},{"t":"case","label":"United States v. Burns","cite":"298 F.3d 523","y":2002,"url":"https://www.courtlistener.com/c/F.3d/298/523/","by":{"1":"25"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"by":{"1":"15, 16, 17, 29, 39"},"q":[{"src":"brief","b":1,"text":"because of an error that was never objected to","cite":"535 U.S. at 634"},{"src":"argument","who":"Ms. Davidson","text":"And I think that can be broken down into two factors: First, for the court to look at what purposes are served by the rule in question, and then to examine the record to see if it demonstrates that those purposes are actually frustrated by the error. So I think that's a type of inquiry that's at least implicit in Cotton and Johnson. In cases like that, errors like that would certainly -"},{"src":"argument","who":"Justice Sotomayor","text":"We've had Cotton, where a drug amount wasn't given to a jury. We look at that third prong as a substantial deprivation of some form of constitutional or state right."},{"src":"argument","who":"Ms. Davidson","text":"And in Cotton, it's not just what the court examined of what the outcome would have been but -- but based on what that record demonstrated."}]},{"t":"case","label":"United States v. Dias","cite":"682 Fed. Appx. 292","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./682/292/","by":{"1":"35"}},{"t":"case","label":"United States v. Dominguez Benitez","cite":"542 U.S. 74","y":2004,"id":"2003/03-167","sc":1,"by":{"1":"10, 14, 17"},"q":[{"src":"brief","b":1,"text":"to encourage timely objections and reduce wasteful reversals by demanding strenuous exertion to get relief for unpreserved error.","cite":"542 U.S. 74, 82"},{"src":"brief","b":1,"text":"is difficult, ‘as it should be.’","cite":"542 U.S. 74, 83 n.9"}]},{"t":"case","label":"United States v. Ellis","cite":"326 F.3d 593","y":2003,"url":"https://www.courtlistener.com/c/F.3d/326/593/","by":{"1":"25"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"Thank you, counsel. Mr. Ellis. ORAL ARGUMENT OF JONATHAN ELLIS ON BEHALF OF THE RESPONDENT"},{"src":"argument","who":"Justice Kagan","text":"Ellis, can -- can I just -- Justice Gorsuch, when he was a judge, wrote this opinion which I'm sure you've read many times, and I just want to quote one sentence from it and then ask you what you think about it because he basically, you know, suggests why you maybe lose. (Laughter.)"},{"src":"argument","who":"Justice Gorsuch","text":"Ellis, if -- if -- along those lines, though, Congress did speak to this question, the feedback loop problem that Justice Breyer has been alluding to, in 3742(f)(1), where it said if there's an error in calculating the sentencing guideline, the case shall be remanded."}]},{"t":"case","label":"United States v. Flores-Mejia","cite":"759 F.3d 253","y":2014,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/759/253/","by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"[r]esentencing imposes a significant burden on district courts: not only do they have to find time in their busy dockets to revisit errors that could have been resolved with a contemporaneous objection at the original sentencing but they also have the burden of reconvening the parties involved, including the defendant, attorneys, witnesses, and law enforcement authorities.","cite":"759 F.3d 253, 258 n.6"}]},{"t":"case","label":"United States v. Hernandez","cite":"690 F.3d 613","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/690/613/","by":{"1":"35"}},{"t":"case","label":"United States v. Lewis","cite":"823 F.3d 1075","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/823/1075/","by":{"1":"32"}},{"t":"case","label":"United States v. Marcus","cite":"560 U.S. 258","y":2010,"id":"2009/08-1341","sc":1,"by":{"1":"14, 15"},"q":[{"src":"brief","b":1,"text":"only where the appellant demonstrates that (1) there is an ‘error’; (2) the error is ‘clear or obvious, rather than subject to reasonable dispute’; (3) the error ‘affected the appellant’s substantial rights, which in the ordinary case means’ it ‘affected the outcome of the district court proceedings’; and (4) ‘the error seriously affect[s] the fairness, integrity or public reputation of judicial proceedings.’","cite":"560 U.S. 258, 262"}]},{"t":"case","label":"United States v. Marroquin","cite":"874 F.3d 851","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/874/851/","by":{"1":"35"}},{"t":"case","label":"United States v. Martinez-Rodriguez","cite":"821 F.3d 659","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/659/","by":{"1":"35"}},{"t":"case","label":"United States v. Mendoza-Velasquez","cite":"847 F.3d 209","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/847/209/","by":{"1":"34"}},{"t":"case","label":"United States v. Miller","cite":"657 Fed. Appx. 265","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./657/265/","by":{"1":"35"}},{"t":"case","label":"United States v. Padilla","cite":"415 F.3d 211","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/415/211/","by":{"1":"32"}},{"t":"case","label":"United States v. Rojas-Ibarra","cite":"669 Fed. Appx. 269","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./669/269/","by":{"1":"35"}},{"t":"case","label":"United States v. Samas","cite":"561 F.3d 108","y":2009,"url":"https://www.courtlistener.com/c/F.3d/561/108/","by":{"1":"25"}},{"t":"case","label":"United States v. Santacruz-Hernandez","cite":"648 Fed. Appx. 456","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./648/456/","by":{"1":"35"}},{"t":"case","label":"United States v. Sarabia-Martinez","cite":"779 F.3d 274","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/779/274/","by":{"1":"9"},"q":[{"src":"brief","b":1,"text":"[t]he fourth prong . . . is not satisfied simply because the ‘plainly’ erroneous sentencing guideline range yields a longer sentence than the range that, on appeal, we perceive as correct.","cite":"779 F.3d 274, 278"}]},{"t":"case","label":"United States v. Segura","cite":"747 F.3d 323","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/747/323/","by":{"1":"9, 33, 34, 35"},"q":[{"src":"brief","b":1,"text":"‘[t]he types of errors that warrant reversal are ones that would shock the conscience of the common man, serve as a powerful indictment against our system of justice, or seriously call into question the competence or integrity of the district judge.’","cite":"747 F.3d 323, 331"},{"src":"brief","b":1,"text":"[t]he types of errors that warrant reversal are ones that would shock the conscience of the common man, serve as a powerful indictment against our system of justice, or seriously call into question the competence or integrity of the district judge.","cite":"747 F.3d 323, 331"}]},{"t":"case","label":"United States v. Solano-Hernandez","cite":"847 F.3d 170","y":2017,"court":"filed May 1","url":"https://www.courtlistener.com/c/F.3d/847/170/","by":{"1":"34"}},{"t":"case","label":"United States v. Vonn","cite":"535 U.S. 55","y":2002,"id":"2001/00-973","sc":1,"by":{"1":"15, 17, 18, 27, 29"},"q":[{"src":"brief","b":1,"text":"require[] defense counsel to be on his toes,","cite":"535 U.S. at 73"},{"src":"brief","b":1,"text":"defense counsel * * * be on his toes, not just the judge.","cite":"535 U.S. at 73"}]},{"t":"case","label":"United States v. Young","cite":"470 U.S. 1","y":1985,"id":"1984/83-469","sc":1,"by":{"1":"passim"},"q":[{"src":"brief","b":1,"text":"tempers the blow of a rigid application of the contemporaneous-objection requirement,","cite":"470 U.S. 1, 15"},{"src":"brief","b":1,"text":"a ‘per se approach to plain-error review is flawed.’","cite":"470 U.S. at 17 n.14"}]},{"t":"case","label":"Wainwright v. Sykes","cite":"433 U.S. 72","y":1977,"id":"1976/75-1578","sc":1,"by":{"1":"17, 18"},"q":[{"src":"brief","b":1,"text":"encourages the result that [trial] proceedings be as free of error as possible.","cite":"433 U.S. 72, 90"}]},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"by":{"1":"13, 28"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"1":"30"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"34"}},{"t":"usc","label":"8 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/8/1326","subs":["(a)","(b)(2)"],"by":{"1":"2, 4, 36, 2, 4, 36"}},{"t":"usc","label":"18 U.S.C. § 3661","url":"https://www.law.cornell.edu/uscode/text/18/3661","by":{"1":"33"}},{"t":"usc","label":"18 U.S.C. § 3771","url":"https://www.law.cornell.edu/uscode/text/18/3771","subs":["(a)"],"by":{"1":"32"}},{"t":"case","label":"Bracy v. Gramley","cite":"520 U.S. 899","y":1997,"id":"1996/96-6133","sc":1,"by":{"2":"11"}},{"t":"case","label":"Kimmelman v. Morrison","cite":"477 U.S. 365","y":1986,"id":"1985/84-1661","sc":1,"by":{"2":"10, 11"}},{"t":"case","label":"Koon v. United States","cite":"518 U.S. 81","y":1996,"id":"1995/94-1664","sc":1,"by":{"2":"4"}},{"t":"case","label":"United States v. Jenkins","cite":"854 F.3d 181","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/854/181/","by":{"2":"5, 6"},"q":[{"src":"brief","b":2,"text":"[a]dditional months in prison are not simply num- bers. Those months have exceptionally severe consequences for the incarcerated individual. They also have consequences both for society which bears the direct and indirect costs of incarceration and for the administration of justice.","cite":"854 F.3d 181, 192"}]},{"t":"case","label":"United States v. Tyson","cite":"863 F.3d 597","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/863/597/","by":{"2":"8"},"q":[{"src":"argument","who":"Ms. Davidson","text":"We -- we cite the Tyson case on page 8 in the yellow brief, and that's a -- a good example of where we have two different inquiries that are informed by the same sort of information, the effect of the guideline."}]},{"t":"case","label":"COURT DOCUMENTS Brief of Plaintiff-Appellee, United States v. Fiallos","cite":"2017 WL 6552177","y":2017,"court":"5th Cir. Dec. 13","by":{"2":"3"}},{"t":"case","label":"Appellee’s Brief, United States v. Fuentes","cite":"2017 WL 5759744","y":2017,"court":"5th Cir. Nov. 20","by":{"2":"3"}},{"t":"case","label":"Original Brief of Appellee, United States v. Washington","cite":"2017 WL 4708216","y":2017,"court":"5th Cir. Oct. 12","by":{"2":"3"}}]};